# ---------- log hub (thread-safe, broadcasts to /ws/logs clients) ----------
class LogHub:
    def __init__(self):
        self.clients = set()
        self.lock = threading.Lock()

    def connect(self, ws):
        with self.lock:
            self.clients.add(ws)

    def disconnect(self, ws):
        with self.lock:
            self.clients.discard(ws)


hub = LogHub()
MAIN_LOOP = None


@app.on_event("startup")
async def _capture_loop():
    global MAIN_LOOP
    MAIN_LOOP = asyncio.get_running_loop()


def broadcast(type_, **data):
    """Thread-safe broadcast to every connected WebSocket client."""
    if MAIN_LOOP is None:
        return
    msg = json.dumps({"type": type_, **data}, ensure_ascii=False)
    for ws in list(hub.clients):
        try:
            asyncio.run_coroutine_threadsafe(ws.send_text(msg), MAIN_LOOP)
        except Exception:
            hub.disconnect(ws)


