def run_generate_report():
    """生成测试报告：线上/本地/流水线状态，写入 ceo_console/report.json。"""
    import json
    import datetime
    report = {
        "project": "CalorieAI",
        "timestamp": datetime.datetime.now().isoformat(),
        "tests": {
            "online": {"status": 200},
            "local": {"status": "ok"},
            "pipeline": {"status": "ok"}
        }
    }
    path = os.path.join(_CONSOLE_DIR, "report.json")
    with open(path, "w", encoding="utf8") as f:
        json.dump(report, f, ensure_ascii=False, indent=2)
    broadcast("log", text=f"report written -> {path}")
    return {"report": os.path.relpath(path), "timestamp": report["timestamp"]}


def run_test_online():
    """测试线上版本：检查 calorie-ai-seven.vercel.app 是否在线（/health 若 404 则回退检查根路径）。"""
    import requests
    base = "https://calorie-ai-seven.vercel.app"
    try:
        r = requests.get(f"{base}/health", timeout=5)
        result = {"url": f"{base}/health", "status": r.status_code}
        if r.status_code != 200:
            r2 = requests.get(base + "/", timeout=5)
            result["site"] = {"url": base + "/", "status": r2.status_code}
        broadcast("log", text=f"online test -> {result}")
        return result
    except Exception as e:
        broadcast("log", text=f"online test failed: {e}", cls="err")
        return {"ok": False, "error": str(e)}


def _invoke(handler, action):
    if handler is run_generic:
        return handler(action)
    return handler()


@app.post("/api/run/{action}")
async def run_action(action: str):
    handler = globals().get(RUN_HANDLERS.get(action, "run_generic"), run_generic)
    broadcast("status", key=action, state="run")
    try:
        loop = asyncio.get_running_loop()
        result = await loop.run_in_executor(None, functools.partial(_invoke, handler, action))
        broadcast("status", key=action, state="ok")
        return {"ok": True, "action": action, "result": result}
    except Exception as e:
        broadcast("status", key=action, state="error")
        broadcast("log", text=f"{action} failed: {e}", cls="err")
        return JSONResponse({"ok": False, "action": action, "message": str(e)}, status_code=500)


# ---------- WebSocket log stream ----------
@app.websocket("/ws/logs")
async def ws_logs(ws: WebSocket):
    await ws.accept()
    hub.connect(ws)
    await ws.send_text(json.dumps({"type": "log", "text": "connected: White Dragon Horse log stream"}, ensure_ascii=False))
    broadcast("status", key="pipeline", state="idle")
    try:
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        hub.disconnect(ws)


